import { readFileSync } from "node:fs";
import pg from "pg";
import { expect, type Page } from "@playwright/test";
// Synthetic local QA accounts generated by scripts/local-qa.ts (never production credentials).
type Accounts = { password: string; accounts: Record<string, string> };
const dir = process.env.E2E_QA_DIR ?? ".local/qa";
export const qa: Accounts = JSON.parse(readFileSync(`${dir}/accounts.json`, "utf8"));
const config = JSON.parse(readFileSync(`${dir}/config.json`, "utf8")) as { ownerPassword: string; databasePort: number };
export type Role = "admin" | "hr" | "commission" | "employee" | "colleague" | "onhold" | "suspended" | "schedule";
export async function login(page: Page, role: Role | string, password = qa.password, remember = false) {
  await page.context().clearCookies();
  await page.goto("/login");
  await page.locator("input[name=email]").fill(qa.accounts[role] ?? role);
  await page.locator("input[name=password]").fill(password);
  if (remember) await page.getByLabel(/Remember me/).check();
  await page.getByRole("button", { name: "Sign in" }).click();
}
export async function signedIn(page: Page, role: Role) { await login(page, role); await page.waitForURL(/\/dashboard/); }
/** Read-only evidence queries against the disposable loopback QA database. */
export async function sql<T extends Record<string, unknown>>(text: string, values: unknown[] = []): Promise<T[]> {
  const client = new pg.Client({ connectionString: `postgresql://employee_owner:${config.ownerPassword}@127.0.0.1:${config.databasePort}/employee_qa` });
  await client.connect(); try { return (await client.query(text, values)).rows as T[]; } finally { await client.end(); }
}
export async function employeeId(number: string) { return (await sql<{ id: string }>("SELECT id FROM employees WHERE employee_number=$1", [number]))[0].id; }
/** Organization-local (Asia/Dhaka) wall-clock values for building schedules relative to now. */
export function dhaka(offsetMinutes = 0) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Dhaka", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23", weekday: "short" }).formatToParts(new Date(Date.now() + offsetMinutes * 60000)).map(p => [p.type, p.value]));
  return { date: `${parts.year}-${parts.month}-${parts.day}`, time: `${parts.hour}:${parts.minute}`, minutes: Number(parts.hour) * 60 + Number(parts.minute), weekday: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(parts.weekday) + 1 };
}
export const addDays = (date: string, days: number) => new Date(Date.parse(`${date}T00:00:00Z`) + days * 86400000).toISOString().slice(0, 10);
export const weekStart = (date: string) => { const d = new Date(`${date}T00:00:00Z`), day = (d.getUTCDay() + 6) % 7; return addDays(date, -day); };
/** Submit a form inside the open dialog and accept its confirmation, if any. */
export async function confirm(page: Page, label: string | RegExp) {
  await page.getByRole("alertdialog").getByRole("button", { name: label }).click();
}
export async function expectToast(page: Page, text: string | RegExp) { await expect(page.getByRole("status").filter({ hasText: text }).first()).toBeVisible(); }
export async function noHorizontalOverflow(page: Page) { expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(await page.evaluate(() => window.innerWidth)); }

/** Creates a synthetic employee with a new login through the real Add employee form. */
export async function createEmployee(page: Page, label: string) {
  const stamp = `${Date.now().toString().slice(-7)}${Math.floor(Math.random() * 90 + 10)}`, email = `e2e.${label}.${stamp}@qa.example.test`, temporary = `Temp-${label}-${stamp}-ok`;
  await page.goto("/manage/employees/new");
  await page.getByLabel("Employee ID").fill(`E2E-${stamp}`); await page.getByLabel("Full legal name").fill(`E2E ${label} ${stamp}`);
  await page.getByLabel("Join date").fill(dhaka().date); // joins today, so synthetic hires never enter past payroll rosters
  await page.getByRole("combobox", { name: "Department", exact: true }).selectOption({ label: "Operations" }); await page.getByRole("combobox", { name: "Position", exact: true }).selectOption({ label: "Operations associate" });
  await page.getByLabel("New login email").fill(email); await page.getByLabel("Temporary password").fill(temporary);
  await page.getByRole("button", { name: "Create employee" }).click();
  await page.waitForURL(/\/manage\/employees\/[0-9a-f-]{36}$/);
  await expect(page.getByRole("heading", { level: 1 })).toContainText(`E2E ${label} ${stamp}`);
  return { id: page.url().split("/").at(-1)!, email, temporary, stamp };
}
